use glam::Vec3;
use crate::{Sim,SimEvent};
use super::{*,act,data::{distance,flat},weapons::jam_chance};
impl Merc{
 pub fn command(&mut self,sim:&mut Sim,a:u32,events:&mut Vec<SimEvent>){if a==0{return;}if self.finished&&self.session{return;}if a==act::ACTIVITY{return;}if a==act::START{self.start(self.merc);self.sync_player(sim);return;}if a==act::PAUSE{if self.screen=="playing"||self.screen=="ending_defend"{self.parent=self.screen.clone();self.open(if self.session{"session_settings"}else{"pause"});}else{self.open("playing");}return;}
 if a&0xf0000000==act::SLIDER {let i=((a>>16)&255) as usize;let q=(a&65535) as f32/65535.;let mut pars=crate::params::list(&mut sim.config.merc);if let Some(p)=pars.get_mut(i){if let crate::params::ParamKind::Float{min,max}=p.kind{let _=crate::params::set(&mut sim.config.merc,&p.path,crate::params::ParamValue::Float((min+(max-min)*q) as f64));}}self.tuning=sim.config.merc.clone();return;}
 if a>=act::WAYPLACE&&a<act::WAYPLACE+100{let i=(a-act::WAYPLACE) as usize;if let Some(p)=self.data.world.place.get(i){self.waypoint=Some(p.pos());self.map_cursor=flat(p.pos());self.flag("waypoint_set");}return;}
 if a>=act::BUY&&a<act::BUY+100 {self.buy((a-act::BUY) as usize);return;}
 if a>=act::TELEPORT&&a<act::TELEPORT+100&&!self.session{let i=(a-act::TELEPORT) as usize;if let Some(p)=self.data.world.place.get(i){self.pos=p.pos()+Vec3::new(0.,0.,30.);self.pos.y=terrain::height(&self.data,self.pos.x,self.pos.z)+0.1;self.riding=None;self.sync_player(sim);}return;}
 if a>=act::STORY&&a<act::STORY+11&&!self.session {self.contract=(a-act::STORY) as usize;self.goal=0;self.contract_active=true;self.goal_time=0.;self.open("playing");return;}
 if a>=act::SELECT&&a<act::SELECT+100{self.focus=(a-act::SELECT) as usize;self.select(sim,events);return;}
 if self.screen!="playing"&&self.screen!="ending_defend"&&self.screen!="card" {self.menu_input(sim,a,events);return;}
 if (4101..=4103).contains(&a){self.active=(a-4101) as usize;return;}
 match a{
 act::BACK=>{if self.map_up{self.map_up=false;}else{self.parent="playing".into();self.open(if self.session{"session_settings"}else{"pause"});}},
 act::MAP=>{self.map_up=!self.map_up;self.monocular=false;self.tracker=false;if self.map_up{self.flag("map_raised");self.map_cursor=flat(self.pos);}},
 act::MONOCULAR=>{self.monocular=!self.monocular;self.map_up=false;self.tracker=false;self.tag_timer=0.;},
 act::TRACKER=>{self.tracker=!self.tracker;self.map_up=false;self.monocular=false;},
 act::NEXT_GUN=>{self.active=(self.active+1)%self.guns.len();self.map_up=false;self.monocular=false;self.tracker=false;self.ammo_time=3.;self.action=Some(Action{kind:"draw".into(),left:0.35,duration:0.35,param:0});},
 act::CROUCH=>{self.stance=if self.stance==1{0}else{1};},act::PRONE=>{self.stance=if self.stance==2{0}else{2};},
 act::RELOAD=>{if let Some(ac)=&mut self.action{if ac.kind=="jam"&&ac.left/ac.duration<0.6&&ac.left/ac.duration>0.3{ac.left*=0.6;self.sound(3);}return;}let g=&self.guns[self.active];let dur=if g.jammed{1.8}else{if g.ammo>=self.data.weapons[g.def].mag||g.reserve<=0{return;}match g.def{1=>3.6,7=>3.2,10=>4.2,11|13=>3.,_=>2.1}};self.action=Some(Action{kind:if g.jammed{"jam"}else{"reload"}.into(),left:dur,duration:dur,param:0});self.ammo_time=dur+3.;self.sound(2);},
 act::HEAL=>{if self.action.is_some(){return;}if self.health<20.{self.action=Some(Action{kind:format!("wound_{}",self.wound),left:4.,duration:4.,param:self.wound as i32});self.sound(6);}else if self.syrettes>0&&self.health<100.{self.syrettes-=1;self.action=Some(Action{kind:"syrette".into(),left:1.5,duration:1.5,param:0});self.sound(5);}},
 act::PILL=>{if self.pills>0&&self.action.is_none(){self.pills-=1;self.action=Some(Action{kind:"pills".into(),left:2.5,duration:2.5,param:0});self.sound(7);}},
 act::THROW=>{if self.action.is_some()||self.safe_town(){return;}let frag=self.throw_frag;let n=if frag{&mut self.grenades}else{&mut self.molotov};if *n<=0{return;}*n-=1;self.action=Some(Action{kind:"throw".into(),left:0.65,duration:0.65,param:frag as i32});},
 act::MELEE=>{if self.action.is_some()||self.safe_town(){return;}self.action=Some(Action{kind:"machete".into(),left:0.5,duration:0.5,param:0});let p=self.eye_pos();let f=self.forward();let target=self.soldiers.iter().enumerate().filter(|(_,n)|n.hp>0.&&distance(n.pos,self.pos)<2.5&&(n.pos+Vec3::Y-p).normalize_or_zero().dot(f)>0.2).map(|(i,_)|i).next();if let Some(i)=target{let stealth=self.soldiers[i].state<2;self.hit_soldier(sim,i,if stealth{200.}else{70.},events);if stealth{self.flag("stealth_kill");}}self.fire.cut.insert(fire::Fire::key(flat(self.pos+f*2.)),0.);self.sound(8);},
 act::INTERACT=>self.interact(sim,events),act::SEAT=>{if self.riding.is_some(){self.seat=1-self.seat;}},act::CAMERA=>{if self.riding.is_some(){self.chase=!self.chase;}else{self.command(sim,act::MELEE,events);}},
 act::PATCH=>self.companion_choice(false),act::OVERDOSE=>{self.action=Some(Action{kind:"overdose".into(),left:2.,duration:2.,param:0});},
 act::WAYPOINT=>{self.waypoint=Some(Vec3::new(self.map_cursor.x,0.,self.map_cursor.y));self.flag("waypoint_set");},
 act::CARD=>{self.parent="playing".into();self.open("contract");},act::BURN=>self.choose_ending(1),act::READ=>self.choose_ending(2),act::CHAIR=>self.choose_ending(3),_=>{}}
 }
 pub fn damage(&mut self,amount:f32,cause:u8){if self.cheats.god||self.attracting||self.death||self.rescue_time>0.{return;}self.health=(self.health-amount).max(0.);self.wound=cause;self.damage_time=3.;if self.health<=0.{if self.session{self.rescue_time=45.;}else if let Some(c)=self.companions.iter_mut().find(|c|c.alive&&c.recruited&&!c.rescue){c.rescue=true;self.rescue_time=6.;self.action=None;}else{self.death=true;self.outcome=Outcome::Lost;self.open("death");}}}
 pub fn action_tick(&mut self,sim:&mut Sim,dt:f32,events:&mut Vec<SimEvent>){if let Some(a)=&mut self.action{a.left-=dt;if a.left>0.{return;}}else{return;}let a=self.action.take().unwrap();match a.kind.as_str(){"jam"=>{self.guns[self.active].jammed=false;self.flag("jam_cleared");self.sound(3);},"reload"=>{let gun=&mut self.guns[self.active];let take=(self.data.weapons[gun.def].mag-gun.ammo).min(gun.reserve);gun.ammo+=take;gun.reserve-=take;self.sound(3);},"pills"=>{self.fever_state=0;self.fever_timer=self.tuning.fever_interval*0.9f32.powi(self.fever_attacks as i32);self.flag("pill_taken");},"syrette"=>{self.health=(self.health+self.tuning.syrette_heal).min(100.);self.damage_time=3.;self.flag("syrette");},"repair"=>{if let Some(i)=(a.param>=0).then_some(a.param as usize){if let Some(v)=self.vehicles.get_mut(i){v.hp=70.;v.fuse=-1.;self.flag("repair_done");}}},"throw"=>{let mut p=self.pos+self.forward()*18.;p.y=terrain::height(&self.data,p.x,p.z);if a.param==1{self.explode(sim,p,6.,150.,events);self.fire.ignite(&self.data,flat(p),2.);self.flag("fire_frag");}else{self.fire.ignite(&self.data,flat(p),4.);self.flag("fire_molotov");}self.sound(9);},"overdose"=>self.companion_choice(true),k if k.starts_with("wound_")=>{self.health=40.;self.damage_time=3.;self.flag(&format!("wound_{}",a.param));},_=>{}}}
 pub fn shoot(&mut self,sim:&mut Sim,events:&mut Vec<SimEvent>){if let Some(i)=self.riding{if self.seat==0{return;}if self.vehicles[i].kind==0||self.vehicles[i].kind==3{self.flag("mounted_gun_fired");}}
 let wi=self.guns[self.active].def;let def=self.data.weapons[wi].clone();let gun=&mut self.guns[self.active];if gun.cooldown>0.||gun.jammed||gun.broken{return;}if gun.ammo<=0{gun.cooldown=0.25;self.sound(1);self.ammo_time=3.;return;}
 if !self.cheats.jams&&sim.state.rng.f32()<jam_chance(gun.condition)*self.tuning.jam{gun.jammed=true;gun.cooldown=0.2;self.sound(1);self.ammo_time=5.;return;}
 if !self.cheats.jams&&gun.condition<self.tuning.break_threshold&&sim.state.rng.f32()<0.03{gun.broken=true;self.action=Some(Action{kind:"break".into(),left:1.,duration:1.,param:0});self.active=(self.active+1)%3;self.flag("weapon_broke");self.sound(10);return;}
 if !self.cheats.ammo{gun.ammo-=1;}gun.condition=(gun.condition-def.wear*self.tuning.wear*if self.reliability.contains(&wi){0.7}else{1.}).max(0.);gun.cooldown=60./def.rpm;let condition=gun.condition;
 self.flash=0.06;self.recoil+=if self.aiming{0.009}else{0.022};self.pitch=(self.pitch+self.recoil).min(1.48);self.sound(20+(wi%5) as u8);self.ammo_time=if self.guns[self.active].ammo<6{2.}else{self.ammo_time};
 let spread=(if self.aiming{0.0015}else{0.009})*(1.+(1.-condition/100.)*0.8)*if self.fever_state==2{3.}else{1.};let mut dir=self.forward()+Vec3::new(sim.state.rng.range(-spread,spread),sim.state.rng.range(-spread,spread),sim.state.rng.range(-spread,spread));dir=dir.normalize();let origin=self.eye_pos();let reach=def.range.max(80.);let wall=crate::projectile::static_hit(&sim.state.physics,origin,dir,reach,None).unwrap_or(reach);let mut best=(wall,None,1.);
 for (i,n) in self.soldiers.iter().enumerate(){if n.hp<=0.{continue;}let center=n.pos+Vec3::Y*0.95;let t=(center-origin).dot(dir);if t<0.||t>best.0{continue;}let hit=origin+dir*t-Vec3::Y*(0.000035*(t-150.).max(0.).powi(2));let dy=hit.y-n.pos.y;let radius=if dy>1.42{0.22}else{0.38};if flat(hit-center).length()<radius&&dy>0.12&&dy<1.88{best=(t,Some(i),if dy>1.42{3.}else if dy<0.6{0.6}else{1.});}}
 let end=origin+dir*best.0;let mut object_hit=None;for (i,o) in self.objects.iter().enumerate(){let t=(o.pos+Vec3::Y-origin).dot(dir);if !o.exploded&&t>0.&&t<best.0&&(o.pos+Vec3::Y-(origin+dir*t)).length()<if o.kind==1{3.}else{0.7}{object_hit=Some(i);best.0=t;}}
 if self.session&&!self.host {self.traces_push(origin,end,false);return;}
 if let Some(i)=object_hit{self.objects[i].hp-=def.damage;if self.objects[i].hp<=0. {self.objects[i].fuse=0.;}}else if let Some(i)=best.1{if wi==9{self.soldiers[i].poison=3.;self.flag("dart_hit");}else{self.hit_soldier(sim,i,def.damage*best.2*self.tuning.player_damage,events);}self.hit_time=0.18;}
 if def.igniter>0{self.fire.ignite(&self.data,flat(end),if wi==12{2.5}else{4.});self.flag(match def.igniter{1=>"fire_flare",2=>"fire_rocket",3=>"fire_flamer",_=>"fire_mortar"});if def.igniter==2||def.igniter==4{self.explode(sim,end,if def.igniter==4{8.}else{6.},def.damage,events);}}
 for v in &mut self.vehicles{let t=(v.pos+Vec3::Y-origin).dot(dir);if !v.exploded&&t>0.&&t<wall&&(v.pos+Vec3::Y-(origin+dir*t)).length()<1.8{v.hp-=def.damage*0.35/self.tuning.vehicle_toughness;}}
 self.traces_push(origin,end,best.1.is_some());self.noise(origin,def.noise);
 if self.contract==1&&!self.coverage.contains("first_jam"){self.guns[self.active].jammed=true;self.flag("first_jam");}
 }
 pub fn traces_push(&mut self,a:Vec3,z:Vec3,hit:bool){self.net_trace(a,z,hit);}
 pub fn hit_soldier(&mut self,sim:&mut Sim,i:usize,damage:f32,events:&mut Vec<SimEvent>){if self.soldiers[i].hp<=0.{return;}self.soldiers[i].hp-=damage;let pos=self.soldiers[i].pos;events.push(SimEvent::Hit{pos:pos+Vec3::Y,strength:0.5,target:None});if self.soldiers[i].hp<=0.{self.kills+=1;self.team_score+=10;self.soldiers[i].state=5;if self.soldiers[i].poison>0.{self.flag("dart_kill");}if let Some(id)=self.soldiers[i].entity.take(){sim.despawn(id);}events.push(SimEvent::Slain{pos,size:0.8});if self.soldiers[i].role==4{self.explode(sim,pos,4.,70.,events);}if self.contract==1&&self.kills==3&&!self.coverage.contains("player_rescued"){self.damage(200.,0);}}else{self.soldiers[i].state=2;self.soldiers[i].detection=1.;}}
 pub fn explode(&mut self,sim:&mut Sim,p:Vec3,r:f32,damage:f32,events:&mut Vec<SimEvent>){events.push(SimEvent::Explosion{pos:p+Vec3::Y,radius:r});self.sound(30);self.fire.ignite(&self.data,flat(p),r*0.6);self.flag("fire_explosion");let targets:Vec<_>=self.soldiers.iter().enumerate().filter(|(_,n)|n.hp>0.&&distance(n.pos,p)<r).map(|(i,_)|i).collect();for i in targets{self.hit_soldier(sim,i,damage,events);}if distance(self.pos,p)<r{self.damage(damage*0.25,1);}for o in &mut self.objects{if !o.exploded&&distance(o.pos,p)<r*1.6{o.hp-=damage;if o.hp<=0.{o.fuse=0.25;}}}for v in &mut self.vehicles{if !v.exploded&&distance(v.pos,p)<r*1.6{v.hp-=damage*0.3/self.tuning.vehicle_toughness;}}}
 pub fn noise(&mut self,p:Vec3,r:f32){for n in &mut self.soldiers{if n.hp>0.&&distance(n.pos,p)<r&&n.state<2{n.state=1;n.timer=10.;}}for a in &mut self.animals{if distance(a.pos,p)<r{a.fleeing=8.;}}if self.animals.iter().any(|a|a.fleeing>0.){self.flag("animals_fled");}}
 pub fn tag(&mut self,dt:f32){let origin=self.eye_pos();let f=self.forward();let target=self.soldiers.iter().enumerate().filter(|(_,n)|n.hp>0.&&(n.pos+Vec3::Y-origin).normalize_or_zero().dot(f)>0.995).map(|(i,_)|i).next();if self.tag_target==target{self.tag_timer+=dt;}else{self.tag_timer=0.;self.tag_target=target;}if self.tag_timer>0.5{if let Some(i)=target{self.soldiers[i].tagged=true;self.flag("monocular_tag");}}}
 pub fn tracker_rate(&self)->f32{let dist=self.caches.iter().filter(|c|!c.found).map(|c|distance(c.pos,self.pos)).fold(1000.,f32::min);if dist>60.{0.}else{1./(0.12+(dist/60.).powi(2)*1.5)}}
 pub fn prompt(&self)->Option<String>{if self.riding.is_some(){return Some("Leave vehicle · change seat".into());}if self.companions.iter().any(|c|c.alive&&c.down>0.&&distance(c.pos,self.pos)<5.){return Some("Help companion".into());}if self.vehicles.iter().any(|v|!v.exploded&&distance(v.pos,self.pos)<5.5){return Some("Drive / hold at hood to repair".into());}if self.caches.iter().any(|c|!c.found&&distance(c.pos,self.pos)<4.){return Some("Open diamond case".into());}let p=self.data.world.place.iter().min_by(|a,b|distance(a.pos(),self.pos).total_cmp(&distance(b.pos(),self.pos)))?;if distance(p.pos(),self.pos)<if p.kind==2{75.}else{27.}{Some(p.name.clone())}else{None}}
 pub fn interact(&mut self,sim:&mut Sim,events:&mut Vec<SimEvent>){if let Some(i)=self.riding.take(){self.pos=self.vehicles[i].pos+Vec3::new(3.,0.,0.);self.pos.y=terrain::height(&self.data,self.pos.x,self.pos.z);self.sync_player(sim);return;}
 if self.session{if let Some(p)=self.peers.iter_mut().find(|p|p.present&&p.hp<=0.&&distance(p.pos,self.pos)<5.){if self.syrettes>0{self.syrettes-=1;p.hp=50.;p.down=0.;self.team_score+=25;self.flag("player_rescued");return;}}}
 if self.companions.iter().any(|c|c.alive&&c.down>0.&&distance(c.pos,self.pos)<5.){self.open("companion");return;}
 if let Some(i)=self.caches.iter().position(|c|!c.found&&distance(c.pos,self.pos)<4.){self.caches[i].found=true;self.diamonds+=self.caches[i].value;if self.tracker{self.flag("cache_tracker");}self.sound(32);self.note(format!("+{} diamonds",self.caches[i].value));return;}
 if self.interact_goal(sim,events){return;}
 if let Some(i)=self.vehicles.iter().position(|v|!v.exploded&&distance(v.pos,self.pos)<5.5){if self.vehicles[i].hp<70.{self.action=Some(Action{kind:"repair".into(),left:if self.upgrades.contains(&2){3.6}else{6.},duration:6.,param:i as i32});self.sound(11);}else{self.riding=Some(i);self.seat=0;self.map_up=false;self.pos=self.vehicles[i].pos;self.flag(if self.vehicles[i].kind==3{"boat_driven"}else{"technical_driven"});}return;}
 if let Some(i)=self.soldiers.iter().position(|n|n.hp<=0.&&distance(n.pos,self.pos)<3.5){self.guns[1]=self.soldiers[i].gun.clone();self.guns[1].ammo=30;self.guns[1].reserve+=60;self.active=1;self.note("A used rifle. Its previous owner cannot recommend it.");return;}
 let p=self.data.world.place.iter().min_by(|a,b|distance(a.pos(),self.pos).total_cmp(&distance(b.pos(),self.pos))).cloned();if let Some(p)=p{if distance(p.pos(),self.pos)>80.{return;}match p.kind{2=>{self.open("town");},3=>{let clear=self.soldiers.iter().all(|n|n.group!=self.data.world.place.iter().position(|q|q.id==p.id).unwrap()||n.hp<=0.);if clear{if let Some(post)=self.posts.iter_mut().find(|a|a.place==p.id){post.claimed=true;}self.flag("safe_house_claimed");self.open("safehouse");}else{self.note("The bed is occupied. Clear the guards.");}},5=>{self.pills=3;self.say("Sister Perpetua",self.s("clinic").to_string());self.open("clinic");},8=>self.open("bus"),_=>{self.collect_tape(&p.id);}}}}
 pub fn companion_choice(&mut self,mercy:bool){if let Some(c)=self.companions.iter_mut().find(|c|c.alive&&c.down>0.&&distance(c.pos,self.pos)<6.){if mercy||c.mortal{c.alive=false;c.down=0.;self.flag("companion_overdosed");self.flag("companion_died");self.say("Companion",self.s("mercy").to_string());}else if self.syrettes>0{self.syrettes-=1;c.down=0.;c.trust+=2;self.flag("companion_patched");self.say("Companion","Put it on the account.");}self.goal_flag=true;self.open("playing");}}
 pub fn buy(&mut self,index:usize){let cost=if index<14{if self.owned.contains(&index){return;}[5,5,4,5,8,10,8,8,12,10,12,12,14,12][index]}else{[6,6,6,8,10,5,7,7][(index-14).min(7)]};let cost=cost+(self.infamy/5).min(3);if self.diamonds<cost{self.note(self.s("no_money").to_string());return;}self.diamonds-=cost;self.flag("diamonds_spent");if index<14{self.owned.insert(index);let slot=self.data.weapons[index].slot;self.guns[slot]=Gun::new(index,&self.data.weapons[index],100.);self.flag("weapon_bought");}else{match index{14=>{self.reliability.insert(self.guns[self.active].def);},15=>{self.accuracy.insert(self.guns[self.active].def);},16..=19=>{self.upgrades.insert(index-16);},_=>self.pills+=3}}self.goal_flag=true;self.sound(32);self.note("Paid in diamonds. Take a fresh crate at any locker.");}
 pub fn collect_tape(&mut self,place:&str){if let Some(i)=self.data.tapes.iter().position(|t|t.place==place){self.tapes.insert(i);self.playing_tape=Some(i);self.tape_line=0;self.tape_timer=0.;self.flag("tape_played");}}
 pub fn tape_tick(&mut self,dt:f32){if let Some(i)=self.playing_tape{self.tape_timer-=dt;if self.tape_timer<=0.{let t=self.data.tapes[i].clone();if let Some(line)=t.lines.get(self.tape_line){self.say(if self.tape_line%2==0{"The Chandler"}else{"Thandiwe Moyo"},line.clone());self.tape_line+=1;self.tape_timer=5.5;}else{self.playing_tape=None;}}}}
}
